*** Begin Patch
*** Add File: /workspace/submission/infra/main.tf
+terraform {
+  required_version = ">= 1.9.0"
+  required_providers {
+    aws = { source = "hashicorp/aws", version = "6.51.0" }
+  }
+  backend "local" { path = "terraform.tfstate" }
+}
+
+variable "config_path" { default = "/workspace/config/config.json" }
+locals {
+  config = jsondecode(file(var.config_path))
+  prefix = local.config.resource_prefix
+  region = local.config.region
+  endpoint = local.config.aws_endpoint_url
+  tags = { ClearLedgerDeployment = local.prefix }
+  zones = ["us-east-1a", "us-east-1b"]
+  log_names = { api = "api", projector = "projector", relay = "outbox-relay", archiver = "audit-archiver" }
+}
+provider "aws" {
+  region = local.region
+  access_key = "test"
+  secret_key = "test"
+  skip_credentials_validation = true
+  skip_requesting_account_id = true
+  skip_metadata_api_check = true
+  skip_region_validation = true
+  s3_use_path_style = true
+  default_tags { tags = local.tags }
+  endpoints {
+    ec2 = local.endpoint
+    elbv2 = local.endpoint
+    ecs = local.endpoint
+    rds = local.endpoint
+    sqs = local.endpoint
+    lambda = local.endpoint
+    scheduler = local.endpoint
+    dynamodb = local.endpoint
+    elasticache = local.endpoint
+    s3 = local.endpoint
+    cognitoidp = local.endpoint
+    iam = local.endpoint
+    kms = local.endpoint
+    cloudwatchlogs = local.endpoint
+    sts = local.endpoint
+  }
+}
+data "aws_caller_identity" "current" {}
+
+resource "aws_vpc" "main" {
+  cidr_block = "10.42.0.0/16"
+  enable_dns_support = true
+  enable_dns_hostnames = true
+  tags = { Name = "${local.prefix}-vpc" }
+}
+resource "aws_subnet" "public" {
+  count = 2
+  vpc_id = aws_vpc.main.id
+  cidr_block = "10.42.${count.index}.0/24"
+  availability_zone = local.zones[count.index]
+  map_public_ip_on_launch = true
+  tags = { Name = "${local.prefix}-public-${count.index}" }
+}
+resource "aws_subnet" "private" {
+  count = 2
+  vpc_id = aws_vpc.main.id
+  cidr_block = "10.42.${count.index + 10}.0/24"
+  availability_zone = local.zones[count.index]
+  map_public_ip_on_launch = false
+  tags = { Name = "${local.prefix}-private-${count.index}" }
+}
+resource "aws_internet_gateway" "main" { vpc_id = aws_vpc.main.id
+  tags = { Name = "${local.prefix}-igw" }
+}
+resource "aws_route_table" "public" {
+  vpc_id = aws_vpc.main.id
+  route { cidr_block = "0.0.0.0/0"
+    gateway_id = aws_internet_gateway.main.id
+  }
+  tags = { Name = "${local.prefix}-public" }
+}
+resource "aws_route_table" "private" {
+  vpc_id = aws_vpc.main.id
+  tags = { Name = "${local.prefix}-private" }
+}
+resource "aws_route_table_association" "public" {
+  count = 2
+  subnet_id = aws_subnet.public[count.index].id
+  route_table_id = aws_route_table.public.id
+}
+resource "aws_route_table_association" "private" {
+  count = 2
+  subnet_id = aws_subnet.private[count.index].id
+  route_table_id = aws_route_table.private.id
+}
+resource "aws_security_group" "alb" {
+  name = "${local.prefix}-alb"
+  vpc_id = aws_vpc.main.id
+  ingress { from_port = 80
+    to_port = 80
+    protocol = "tcp"
+    cidr_blocks = ["0.0.0.0/0"]
+  }
+  egress { from_port = 8080
+    to_port = 8080
+    protocol = "tcp"
+    cidr_blocks = [aws_vpc.main.cidr_block]
+  }
+}
+resource "aws_security_group" "ecs" {
+  name = "${local.prefix}-ecs"
+  vpc_id = aws_vpc.main.id
+  ingress { from_port = 8080
+    to_port = 8080
+    protocol = "tcp"
+    security_groups = [aws_security_group.alb.id]
+  }
+  egress { from_port = 0
+    to_port = 0
+    protocol = "-1"
+    cidr_blocks = ["0.0.0.0/0"]
+  }
+}
+resource "aws_security_group" "rds" {
+  name = "${local.prefix}-rds"
+  vpc_id = aws_vpc.main.id
+  ingress { from_port = 5432
+    to_port = 5432
+    protocol = "tcp"
+    security_groups = [aws_security_group.ecs.id]
+  }
+  egress = []
+}
+resource "aws_security_group" "valkey" {
+  name = "${local.prefix}-valkey"
+  vpc_id = aws_vpc.main.id
+  ingress { from_port = 6379
+    to_port = 6379
+    protocol = "tcp"
+    security_groups = [aws_security_group.ecs.id]
+  }
+  egress = []
+}
+
+resource "aws_kms_key" "keys" {
+  for_each = toset(["database", "messaging", "projection", "audit"])
+  description = "${local.prefix}-${each.key}"
+  enable_key_rotation = true
+  deletion_window_in_days = 10
+}
+resource "aws_kms_alias" "keys" {
+  for_each = aws_kms_key.keys
+  name = "alias/${local.prefix}-${each.key}"
+  target_key_id = each.value.key_id
+}
+resource "aws_cloudwatch_log_group" "logs" {
+  for_each = local.log_names
+  name = "/clearledger/${local.prefix}/${each.value}"
+  retention_in_days = 14
+}
+resource "aws_db_subnet_group" "main" {
+  name = "${local.prefix}-db"
+  subnet_ids = aws_subnet.private[*].id
+}
+resource "aws_db_instance" "main" {
+  identifier = "${local.prefix}-postgres"
+  engine = "postgres"
+  engine_version = "16.3"
+  instance_class = "db.t4g.micro"
+  allocated_storage = 20
+  db_name = local.config.db_name
+  username = local.config.db_username
+  password = local.config.db_password
+  storage_encrypted = true
+  kms_key_id = aws_kms_key.keys["database"].arn
+  publicly_accessible = false
+  skip_final_snapshot = true
+  db_subnet_group_name = aws_db_subnet_group.main.name
+  vpc_security_group_ids = [aws_security_group.rds.id]
+  apply_immediately = true
+}
+resource "aws_dynamodb_table" "projection" {
+  name = "${local.prefix}-projections"
+  billing_mode = "PAY_PER_REQUEST"
+  hash_key = "PK"
+  range_key = "SK"
+  dynamic "attribute" {
+    for_each = toset(["PK", "SK", "GSI1PK", "GSI1SK"])
+    content { name = attribute.value
+      type = "S"
+    }
+  }
+  global_secondary_index { name = "AccountIndex"
+    hash_key = "GSI1PK"
+    range_key = "GSI1SK"
+    projection_type = "ALL"
+  }
+  point_in_time_recovery { enabled = true }
+  server_side_encryption { enabled = true
+    kms_key_arn = aws_kms_key.keys["projection"].arn
+  }
+}
+resource "aws_elasticache_subnet_group" "main" {
+  name = "${local.prefix}-cache"
+  subnet_ids = aws_subnet.private[*].id
+}
+resource "aws_elasticache_replication_group" "main" {
+  replication_group_id = "${local.prefix}-valkey"
+  description = "${local.prefix} projection cache"
+  engine = "valkey"
+  engine_version = "8.0"
+  node_type = "cache.t4g.micro"
+  num_cache_clusters = 1
+  port = 6379
+  subnet_group_name = aws_elasticache_subnet_group.main.name
+  security_group_ids = [aws_security_group.valkey.id]
+  automatic_failover_enabled = false
+  transit_encryption_enabled = false
+  at_rest_encryption_enabled = false
+  apply_immediately = true
+}
+resource "aws_s3_bucket" "audit" {
+  bucket = "${local.prefix}-audit"
+  force_destroy = true
+}
+resource "aws_s3_bucket_versioning" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  versioning_configuration { status = "Enabled" }
+}
+resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  rule { apply_server_side_encryption_by_default {
+      sse_algorithm = "aws:kms"
+      kms_master_key_id = aws_kms_key.keys["audit"].arn
+    }
+  }
+}
+resource "aws_s3_bucket_public_access_block" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  block_public_acls = true
+  block_public_policy = true
+  ignore_public_acls = true
+  restrict_public_buckets = true
+}
+resource "aws_sqs_queue" "dlq" {
+  name = "${local.prefix}-events-dlq"
+  kms_master_key_id = aws_kms_key.keys["messaging"].arn
+  message_retention_seconds = 1209600
+}
+resource "aws_sqs_queue" "main" {
+  name = "${local.prefix}-events"
+  kms_master_key_id = aws_kms_key.keys["messaging"].arn
+  visibility_timeout_seconds = 3
+  receive_wait_time_seconds = 2
+  message_retention_seconds = 172800
+  redrive_policy = jsonencode({ deadLetterTargetArn = aws_sqs_queue.dlq.arn, maxReceiveCount = 4 })
+}
+resource "aws_cognito_user_pool" "main" { name = "${local.prefix}-auth" }
+resource "aws_cognito_resource_server" "main" {
+  name = "${local.prefix}-clearledger"
+  identifier = "clearledger"
+  user_pool_id = aws_cognito_user_pool.main.id
+  dynamic "scope" {
+    for_each = toset(["read", "write", "admin"])
+    content { scope_name = scope.value
+      scope_description = "ClearLedger ${scope.value}"
+    }
+  }
+}
+resource "aws_cognito_user_pool_client" "clients" {
+  for_each = toset(["read", "write", "admin"])
+  name = "${local.prefix}-${each.key}"
+  user_pool_id = aws_cognito_user_pool.main.id
+  generate_secret = true
+  allowed_oauth_flows_user_pool_client = true
+  allowed_oauth_flows = ["client_credentials"]
+  allowed_oauth_scopes = ["${aws_cognito_resource_server.main.identifier}/${each.key}"]
+}
+
+locals {
+  database_url = "postgres://${urlencode(local.config.db_username)}:${urlencode(local.config.db_password)}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${local.config.db_name}"
+  valkey_url = "redis://${aws_elasticache_replication_group.main.primary_endpoint_address}:6379"
+  common_env = {
+    AWS_REGION = local.region, AWS_DEFAULT_REGION = local.region,
+    AWS_ACCESS_KEY_ID = "test", AWS_SECRET_ACCESS_KEY = "test", AWS_ENDPOINT_URL = local.endpoint
+  }
+  worker_env = {
+    projector = { PROJECTION_TABLE = aws_dynamodb_table.projection.name, VALKEY_URL = local.valkey_url }
+    relay = { DATABASE_URL = local.database_url, SQS_QUEUE_URL = aws_sqs_queue.main.url, OUTBOX_BATCH_SIZE = "50" }
+    archiver = { DATABASE_URL = local.database_url, AUDIT_BUCKET = aws_s3_bucket.audit.bucket, AUDIT_PREFIX = "ledger-audit/" }
+  }
+  worker_images = { projector = local.config.projector_image, relay = local.config.relay_image, archiver = local.config.archiver_image }
+}
+resource "aws_lambda_function" "workers" {
+  for_each = local.worker_images
+  function_name = "${local.prefix}-${local.log_names[each.key]}"
+  package_type = "Image"
+  image_uri = each.value
+  role = aws_iam_role.roles[each.key].arn
+  timeout = 3
+  memory_size = 256
+  environment { variables = merge(local.common_env, local.worker_env[each.key], { CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.logs[each.key].name }) }
+  depends_on = [aws_iam_role_policy.canonical]
+}
+resource "aws_lambda_event_source_mapping" "projector" {
+  event_source_arn = aws_sqs_queue.main.arn
+  function_name = aws_lambda_function.workers["projector"].arn
+  enabled = true
+  batch_size = 5
+  maximum_batching_window_in_seconds = 0
+  function_response_types = ["ReportBatchItemFailures"]
+}
+resource "aws_scheduler_schedule" "schedules" {
+  for_each = { relay = "rate(1 minute)", archiver = "rate(5 minutes)" }
+  name = "${local.prefix}-${local.log_names[each.key]}"
+  state = "ENABLED"
+  schedule_expression = each.value
+  flexible_time_window { mode = "OFF" }
+  target { arn = aws_lambda_function.workers[each.key].arn
+    role_arn = aws_iam_role.roles["scheduler"].arn
+    input = "{}"
+  }
+}
+resource "aws_lb" "main" {
+  name = "${local.prefix}-alb"
+  internal = false
+  load_balancer_type = "application"
+  subnets = aws_subnet.public[*].id
+  security_groups = [aws_security_group.alb.id]
+}
+resource "aws_lb_target_group" "api" {
+  name = "${local.prefix}-api"
+  vpc_id = aws_vpc.main.id
+  port = 8080
+  protocol = "HTTP"
+  target_type = "ip"
+  health_check { path = "/health/ready"
+    protocol = "HTTP"
+    matcher = "200"
+    interval = 5
+    healthy_threshold = 2
+    unhealthy_threshold = 2
+  }
+}
+resource "aws_lb_listener" "http" {
+  load_balancer_arn = aws_lb.main.arn
+  port = 80
+  protocol = "HTTP"
+  default_action { type = "forward"
+    target_group_arn = aws_lb_target_group.api.arn
+  }
+}
+resource "aws_ecs_cluster" "main" {
+  name = "${local.prefix}-cluster"
+  setting { name = "containerInsights"
+    value = "enabled"
+  }
+}
+resource "aws_ecs_task_definition" "api" {
+  family = "${local.prefix}-api"
+  requires_compatibilities = ["FARGATE"]
+  network_mode = "awsvpc"
+  cpu = "256"
+  memory = "512"
+  execution_role_arn = aws_iam_role.roles["ecs_execution"].arn
+  task_role_arn = aws_iam_role.roles["ecs_task"].arn
+  container_definitions = jsonencode([{
+    name = "api", image = local.config.api_image, essential = true,
+    portMappings = [{ containerPort = 8080, hostPort = 8080, protocol = "tcp" }],
+    environment = [for k, v in merge(local.common_env, {
+      PORT = "8080", DATABASE_URL = local.database_url, SQS_QUEUE_URL = aws_sqs_queue.main.url,
+      PROJECTION_TABLE = aws_dynamodb_table.projection.name, VALKEY_URL = local.valkey_url,
+      CACHE_TTL_SECONDS = "90", AUTH_ISSUER = "${local.endpoint}/${aws_cognito_user_pool.main.id}",
+      AUTH_JWKS_URL = "${local.endpoint}/${aws_cognito_user_pool.main.id}/.well-known/jwks.json",
+      AUTH_AUDIENCES = join(",", [for k in ["read", "write", "admin"] : aws_cognito_user_pool_client.clients[k].id]),
+      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.logs["api"].name
+    }) : { name = k, value = v }],
+    logConfiguration = { logDriver = "awslogs", options = {
+      awslogs-group = aws_cloudwatch_log_group.logs["api"].name, awslogs-region = local.region, awslogs-stream-prefix = "api"
+    } }
+  }])
+}
+resource "aws_ecs_service" "api" {
+  name = "${local.prefix}-api"
+  cluster = aws_ecs_cluster.main.id
+  task_definition = aws_ecs_task_definition.api.arn
+  launch_type = "FARGATE"
+  desired_count = 2
+  network_configuration { subnets = aws_subnet.private[*].id
+    security_groups = [aws_security_group.ecs.id]
+    assign_public_ip = false
+  }
+  load_balancer { target_group_arn = aws_lb_target_group.api.arn
+    container_name = "api"
+    container_port = 8080
+  }
+  depends_on = [aws_lb_listener.http, aws_iam_role_policy.canonical]
+}
*** Add File: /workspace/submission/infra/iam.tf
+locals {
+  role_services = { ecs_execution = "ecs-tasks", ecs_task = "ecs-tasks", projector = "lambda", relay = "lambda", archiver = "lambda", scheduler = "scheduler" }
+  role_logs = { ecs_execution = "api", ecs_task = "api", projector = "projector", relay = "relay", archiver = "archiver", scheduler = "" }
+  role_keys = { ecs_execution = [], ecs_task = ["messaging", "projection"], projector = ["messaging", "projection"], relay = ["messaging", "database"], archiver = ["audit", "database"], scheduler = [] }
+  table_resources = [aws_dynamodb_table.projection.arn, "${aws_dynamodb_table.projection.arn}/index/AccountIndex"]
+  bucket_resources = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]
+  sqs_actions = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
+  dynamo_actions = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
+  s3_actions = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
+  lambda_arns = { for k in ["projector", "relay", "archiver"] : k => "arn:aws:lambda:${local.region}:${data.aws_caller_identity.current.account_id}:function:${local.prefix}-${local.log_names[k]}" }
+  extra_allow = {
+    ecs_execution = []
+    ecs_task = [
+      { Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"], Resource = local.table_resources }
+    ]
+    projector = [
+      { Effect = "Allow", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Allow", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"], Resource = local.table_resources }
+    ]
+    relay = [{ Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = [aws_sqs_queue.main.arn] }]
+    archiver = [
+      { Effect = "Allow", Action = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"], Resource = ["${aws_s3_bucket.audit.arn}/ledger-audit/*"] },
+      { Effect = "Allow", Action = ["s3:ListBucket", "s3:GetBucketLocation"], Resource = [aws_s3_bucket.audit.arn] }
+    ]
+    scheduler = [{ Effect = "Allow", Action = ["lambda:InvokeFunction"], Resource = [local.lambda_arns.relay, local.lambda_arns.archiver] }]
+  }
+  extra_deny = {
+    ecs_execution = [
+      { Effect = "Deny", Action = local.sqs_actions, Resource = [aws_sqs_queue.main.arn, aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = local.dynamo_actions, Resource = local.table_resources },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_resources }
+    ]
+    ecs_task = [
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = local.sqs_actions, Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = local.table_resources },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_resources }
+    ]
+    projector = [
+      { Effect = "Deny", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = local.table_resources },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_resources }
+    ]
+    relay = [
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = local.sqs_actions, Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = local.dynamo_actions, Resource = local.table_resources },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_resources }
+    ]
+    archiver = [
+      { Effect = "Deny", Action = ["s3:DeleteObject", "s3:DeleteObjectVersion"], Resource = local.bucket_resources },
+      { Effect = "Deny", Action = local.sqs_actions, Resource = [aws_sqs_queue.main.arn, aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = local.dynamo_actions, Resource = local.table_resources }
+    ]
+    scheduler = [
+      { Effect = "Deny", Action = ["lambda:InvokeFunction"], Resource = [local.lambda_arns.projector] },
+      { Effect = "Deny", Action = local.sqs_actions, Resource = [aws_sqs_queue.main.arn, aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = local.dynamo_actions, Resource = local.table_resources },
+      { Effect = "Deny", Action = local.s3_actions, Resource = local.bucket_resources }
+    ]
+  }
+}
+resource "aws_iam_role" "roles" {
+  for_each = local.role_services
+  name = "${local.prefix}-${each.key}"
+  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{ Effect = "Allow", Action = "sts:AssumeRole", Principal = { Service = "${each.value}.amazonaws.com" } }] })
+}
+resource "aws_iam_role_policy" "canonical" {
+  for_each = local.role_services
+  name = "${local.prefix}-${each.key}-canonical"
+  role = aws_iam_role.roles[each.key].id
+  policy = jsonencode({ Version = "2012-10-17", Statement = concat(
